mapper.select:
SELECT uf.id as attentionId, uf.follower_id as followerId, -- 关注关系的发起者（即列表所属者） u.id as userId, -- 被关注者的用户ID u.user_id as userUid, -- 被关注者的UID u.nickname, u.avatar_url as avatarUrl, uf.create_time as createTime,
CASE WHEN viewer_uf.id IS NOT NULL THEN 1 ELSE 0 END as isMyFollowing
0 as isMyFollowing
FROM user_follow uf INNER JOIN user u ON uf.following_id = u.user_id -- 关联被关注者的信息
LEFT JOIN user_follow viewer_uf ON viewer_uf.following_id = u.user_id AND viewer_uf.follower_id = #{viewerId}
WHERE uf.follower_id = #{follower} -- 列表所属者 ORDER BY uf.create_time DESC;

SELECT uf.id as attentionId, uf.following_id as followerId, -- 这里 followerId 字段复用为「列表所属者」 u.id as userId, -- 粉丝的内部主键 u.user_id as userUid, -- 粉丝的 UID u.nickname, u.avatar_url as avatarUrl, uf.create_time as createTime,
CASE WHEN viewer_uf.id IS NOT NULL THEN 1 ELSE 0 END as isMyFollowing
0 as isMyFollowing
FROM user_follow uf INNER JOIN user u ON uf.follower_id = u.user_id -- 关联粉丝资料
LEFT JOIN user_follow viewer_uf ON viewer_uf.following_id = u.user_id AND viewer_uf.follower_id = #{viewerId}
WHERE uf.following_id = #{following} -- 列表所属者 = 被关注者 ORDER BY uf.create_time DESC;
